package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;

import org.junit.jupiter.api.Test;

class StatementIndexBuildTest {
	@Test
	void durableBuildPreservesTheConfiguredPrimaryAndSecondaryIndexOrder() throws Exception {
		List<String> requested = new ArrayList<>(List.of("spoc", "ospc", "posc", "psoc"));
		for (int rotation = 0; rotation < requested.size(); rotation++) {
			List<String> expected = List.copyOf(requested);
			var build = new StatementIndexBuild(StatementIndexBuild.Phase.COPY, new LinkedHashSet<>(requested),
					new LinkedHashSet<>(requested), true, new byte[0], 1L);
			var resumed = StatementIndexBuild.decode(build.encode(2L));
			assertNotNull(resumed);
			assertAll("primary and secondary index order must survive descriptor creation and restart",
					() -> assertEquals(expected, List.copyOf(build.source())),
					() -> assertEquals(expected, List.copyOf(build.target())),
					() -> assertEquals(expected, List.copyOf(resumed.source())),
					() -> assertEquals(expected, List.copyOf(resumed.target())));
			Collections.rotate(requested, 1);
		}
	}
}
